import React, { useState } from 'react';
import './EncryptionChat.css';

const EncryptionChat = () => {
  const [inputMessage, setInputMessage] = useState('');
  const [selectedCipher, setSelectedCipher] = useState('caesar');
  const [encryptionKey, setEncryptionKey] = useState('');
  const [encryptedMessage, setEncryptedMessage] = useState('');
  const [showCipherDropdown, setShowCipherDropdown] = useState(false);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  // Caesar Cipher Implementation
  const caesarEncrypt = (text, key) => {
    const shift = parseInt(key) || 0;
    return text.toUpperCase().split('').map(char => {
      if (char >= 'A' && char <= 'Z') {
        return String.fromCharCode((char.charCodeAt(0) - 65 + shift) % 26 + 65);
      }
      return char;
    }).join('');
  };

  const caesarDecrypt = (text, key) => {
    const shift = parseInt(key) || 0;
    return text.toUpperCase().split('').map(char => {
      if (char >= 'A' && char <= 'Z') {
        return String.fromCharCode((char.charCodeAt(0) - 65 - shift + 26) % 26 + 65);
      }
      return char;
    }).join('');
  };

  // Vigenere Cipher Implementation
  const vigenereEncrypt = (text, key) => {
    const keyUpper = key.toUpperCase().replace(/[^A-Z]/g, '');
    if (!keyUpper) return text.toUpperCase();

    let keyIndex = 0;
    return text.toUpperCase().split('').map(char => {
      if (char >= 'A' && char <= 'Z') {
        const keyChar = keyUpper[keyIndex % keyUpper.length];
        const shift = keyChar.charCodeAt(0) - 65;
        keyIndex++;
        return String.fromCharCode((char.charCodeAt(0) - 65 + shift) % 26 + 65);
      }
      return char;
    }).join('');
  };

  const vigenereDecrypt = (text, key) => {
    const keyUpper = key.toUpperCase().replace(/[^A-Z]/g, '');
    if (!keyUpper) return text.toUpperCase();

    let keyIndex = 0;
    return text.toUpperCase().split('').map(char => {
      if (char >= 'A' && char <= 'Z') {
        const keyChar = keyUpper[keyIndex % keyUpper.length];
        const shift = keyChar.charCodeAt(0) - 65;
        keyIndex++;
        return String.fromCharCode((char.charCodeAt(0) - 65 - shift + 26) % 26 + 65);
      }
      return char;
    }).join('');
  };

  // Rail Fence Cipher Implementation
  const railFenceEncrypt = (text, key) => {
    const rails = parseInt(key) || 3;
    if (rails < 2) return text.toUpperCase();

    const fence = Array(rails).fill().map(() => []);
    let rail = 0;
    let direction = 1;

    for (let i = 0; i < text.length; i++) {
      fence[rail].push(text[i]);
      rail += direction;
      if (rail === 0 || rail === rails - 1) direction *= -1;
    }

    return fence.flat().join('').toUpperCase();
  };

  const railFenceDecrypt = (text, key) => {
    const rails = parseInt(key) || 3;
    if (rails < 2) return text.toUpperCase();

    const fence = Array(rails).fill().map(() => []);
    let rail = 0;
    let direction = 1;

    // Mark positions
    for (let i = 0; i < text.length; i++) {
      fence[rail].push(null);
      rail += direction;
      if (rail === 0 || rail === rails - 1) direction *= -1;
    }

    // Fill with characters
    let index = 0;
    for (let r = 0; r < rails; r++) {
      for (let c = 0; c < fence[r].length; c++) {
        if (fence[r][c] === null) {
          fence[r][c] = text[index++];
        }
      }
    }

    // Read in zigzag pattern
    let result = '';
    rail = 0;
    direction = 1;
    for (let i = 0; i < text.length; i++) {
      result += fence[rail].shift();
      rail += direction;
      if (rail === 0 || rail === rails - 1) direction *= -1;
    }

    return result.toUpperCase();
  };

  // Playfair Cipher Implementation
  const generatePlayfairMatrix = (key) => {
    const keyUpper = key.toUpperCase().replace(/[^A-Z]/g, '').replace(/J/g, 'I');
    const alphabet = 'ABCDEFGHIKLMNOPQRSTUVWXYZ';
    const seen = new Set();
    const matrix = [];

    // Add key characters
    for (const char of keyUpper) {
      if (!seen.has(char)) {
        seen.add(char);
        matrix.push(char);
      }
    }

    // Add remaining alphabet
    for (const char of alphabet) {
      if (!seen.has(char)) {
        seen.add(char);
        matrix.push(char);
      }
    }

    return matrix;
  };

  const playfairEncrypt = (text, key) => {
    const matrix = generatePlayfairMatrix(key);
    const processedText = text.toUpperCase().replace(/[^A-Z]/g, '').replace(/J/g, 'I');

    // Prepare digraphs
    const digraphs = [];
    let i = 0;
    while (i < processedText.length) {
      let pair = processedText[i];
      i++;
      if (i < processedText.length && processedText[i] !== pair) {
        pair += processedText[i];
        i++;
      } else {
        pair += 'X';
      }
      digraphs.push(pair);
    }

    // Encrypt digraphs
    const result = digraphs.map(([a, b]) => {
      const posA = matrix.indexOf(a);
      const posB = matrix.indexOf(b);
      const rowA = Math.floor(posA / 5);
      const colA = posA % 5;
      const rowB = Math.floor(posB / 5);
      const colB = posB % 5;

      if (rowA === rowB) {
        // Same row
        return matrix[rowA * 5 + (colA + 1) % 5] + matrix[rowB * 5 + (colB + 1) % 5];
      } else if (colA === colB) {
        // Same column
        return matrix[((rowA + 1) % 5) * 5 + colA] + matrix[((rowB + 1) % 5) * 5 + colB];
      } else {
        // Rectangle
        return matrix[rowA * 5 + colB] + matrix[rowB * 5 + colA];
      }
    });

    return result.join('');
  };

  const playfairDecrypt = (text, key) => {
    const matrix = generatePlayfairMatrix(key);
    const processedText = text.toUpperCase().replace(/[^A-Z]/g, '');

    // Split into digraphs
    const digraphs = [];
    for (let i = 0; i < processedText.length; i += 2) {
      digraphs.push(processedText.substr(i, 2));
    }

    // Decrypt digraphs
    const result = digraphs.map(([a, b]) => {
      const posA = matrix.indexOf(a);
      const posB = matrix.indexOf(b);
      const rowA = Math.floor(posA / 5);
      const colA = posA % 5;
      const rowB = Math.floor(posB / 5);
      const colB = posB % 5;

      if (rowA === rowB) {
        // Same row
        return matrix[rowA * 5 + (colA + 4) % 5] + matrix[rowB * 5 + (colB + 4) % 5];
      } else if (colA === colB) {
        // Same column
        return matrix[((rowA + 4) % 5) * 5 + colA] + matrix[((rowB + 4) % 5) * 5 + colB];
      } else {
        // Rectangle
        return matrix[rowA * 5 + colB] + matrix[rowB * 5 + colA];
      }
    });

    return result.join('');
  };

  const encryptMessage = (text, cipher, key) => {
    switch (cipher) {
      case 'caesar':
        return caesarEncrypt(text, key);
      case 'vigenere':
        return vigenereEncrypt(text, key);
      case 'railfence':
        return railFenceEncrypt(text, key);
      case 'playfair':
        return playfairEncrypt(text, key);
      default:
        return text;
    }
  };

  const decryptMessage = (text, cipher, key) => {
    switch (cipher) {
      case 'caesar':
        return caesarDecrypt(text, key);
      case 'vigenere':
        return vigenereDecrypt(text, key);
      case 'railfence':
        return railFenceDecrypt(text, key);
      case 'playfair':
        return playfairDecrypt(text, key);
      default:
        return text;
    }
  };

  const handleSendMessage = () => {
    if (!inputMessage.trim() || !encryptionKey.trim()) {
      alert('Please enter both message and encryption key');
      return;
    }

    const encrypted = encryptMessage(inputMessage, selectedCipher, encryptionKey);
    const decrypted = decryptMessage(encrypted, selectedCipher, encryptionKey);

    const newMessage = {
      id: Date.now(),
      sender: currentUser,
      original: inputMessage.toUpperCase(),
      encrypted: encrypted,
      decrypted: decrypted,
      cipher: selectedCipher,
      key: encryptionKey,
      timestamp: new Date().toLocaleTimeString()
    };

    setMessages([...messages, newMessage]);
    setInputMessage('');

    // Switch user for next message
    setCurrentUser(currentUser === 'User A' ? 'User B' : 'User A');
  };

  const handleCipherSelect = (cipher) => {
    setSelectedCipher(cipher);
    setShowCipherMenu(false);
  };

  const resetChat = () => {
    setMessages([]);
    setInputMessage('');
    setEncryptionKey('');
    setShowCipherMenu(true);
    setCurrentUser('User A');
  };

  return (
    <div className="encryption-chat">
      <div className="chat-header">
        <h1><i className="lock-icon">🔒</i> Encryption Chat Program</h1>
        <button onClick={resetChat} className="reset-btn">Reset Chat</button>
      </div>

      {showCipherMenu && (
        <div className="cipher-menu">
          <h2>Choose Cipher Algorithm:</h2>
          <div className="cipher-options">
            <button onClick={() => handleCipherSelect('caesar')} className="cipher-btn">
              <h3>1. Caesar Cipher</h3>
              <p>Shift each letter by key positions</p>
            </button>
            <button onClick={() => handleCipherSelect('vigenere')} className="cipher-btn">
              <h3>2. Vigenere Cipher</h3>
              <p>Use repeating keyword shifts</p>
            </button>
            <button onClick={() => handleCipherSelect('railfence')} className="cipher-btn">
              <h3>3. Rail Fence Cipher</h3>
              <p>Rearrange characters by rails</p>
            </button>
            <button onClick={() => handleCipherSelect('playfair')} className="cipher-btn">
              <h3>4. Playfair Cipher</h3>
              <p>Encrypt using digraph substitution</p>
            </button>
          </div>
        </div>
      )}

      {!showCipherMenu && (
        <>
          <div className="cipher-info">
            <span className="current-cipher">
              <strong>Selected Cipher:</strong> {selectedCipher.charAt(0).toUpperCase() + selectedCipher.slice(1)}
            </span>
            <button onClick={() => setShowCipherMenu(true)} className="change-cipher-btn">
              Change Cipher
            </button>
          </div>

          <div className="chat-container">
            <div className="messages-area">
              {messages.length === 0 && (
                <div className="welcome-message">
                  <p>Welcome to Encryption Chat! Choose a cipher and start sending encrypted messages.</p>
                </div>
              )}

              {messages.map((msg) => (
                <div key={msg.id} className="message">
                  <div className="message-header">
                    <span className="sender">{msg.sender}</span>
                    <span className="timestamp">{msg.timestamp}</span>
                  </div>
                  <div className="message-content">
                    <div className="original">
                      <span className="label">Original:</span> {msg.original}
                    </div>
                    <div className="encrypted">
                      <span className="label">Encrypted:</span> 
                      <span className="ciphertext">{msg.encrypted}</span>
                    </div>
                    <div className="decrypted">
                      <span className="label">Decrypted:</span> {msg.decrypted}
                    </div>
                    <div className="cipher-info-small">
                      <span className="label">Cipher:</span> {msg.cipher} | 
                      <span className="label">Key:</span> {msg.key}
                    </div>
                  </div>
                </div>
              ))}
              <div ref={messagesEndRef} />
            </div>

            <div className="input-area">
              <div className="key-input">
                <label>Encryption Key:</label>
                <input
                  type="text"
                  value={encryptionKey}
                  onChange={(e) => setEncryptionKey(e.target.value)}
                  placeholder="Enter encryption key"
                  className="key-field"
                />
              </div>
              <div className="message-input">
                <textarea
                  value={inputMessage}
                  onChange={(e) => setInputMessage(e.target.value)}
                  placeholder="Type your message..."
                  className="message-field"
                  onKeyPress={(e) => {
                    if (e.key === 'Enter' && !e.shiftKey) {
                      e.preventDefault();
                      handleSendMessage();
                    }
                  }}
                />
                <button onClick={handleSendMessage} className="send-btn">
                  Send Encrypted Message
                </button>
              </div>
            </div>
          </div>
        </>
      )}
    </div>
  );
};

export default EncryptionChat;
